        "arguments": {
          "proposals": [
            {
              "itemId": "ARCH-01",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Die Festlegung auf eine reine Mobile-App ist eine Architekturentscheidung und schränkt betroffene Umsetzungsarbeit auf mobile Plattformen ohne Web-Client ein.",
              "targetPbiIds": [
                "PBI-001",
                "PBI-025",
                "PBI-030"
              ]
            },
            {
              "itemId": "ARCH-02",
              "roles": [
                "constraint"
              ],
              "rationale": "Die Priorisierung, dass die App vor allem dem besseren Verstehen durch Betreuer und andere Personen dient, setzt einen fachlichen Rahmen für Produktziel und Lösungszuschnitt.",
              "targetPbiIds": [
                "PBI-001"
              ]
            },
            {
              "itemId": "ARCH-03",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Der Kernansatz, Profil- und Kommunikationswissen zum Nachschlagen bereitzustellen, ist eine dokumentierbare Lösungsentscheidung und rahmt die inhaltliche Ausgestaltung der Kernfunktionen.",
              "targetPbiIds": [
                "PBI-001",
                "PBI-012",
                "PBI-013",
                "PBI-018"
              ]
            },
            {
              "itemId": "ARCH-04",
              "roles": [
                "constraint"
              ],
              "rationale": "Der Ausschluss eines bidirektionalen individuellen Übersetzers grenzt den Lösungsraum fachlich klar ein und beschränkt damit das Produktziel.",
              "targetPbiIds": [
                "PBI-001"
              ]
            },
            {
              "itemId": "ARCH-05",
              "roles": [
                "constraint"
              ],
              "rationale": "Die bestehende Akten- und Dokumentationslage ist ein Rahmen für Entscheidungen zur Dokumentationsintegration und möglichen Datenübernahme.",
              "targetPbiIds": [
                "PBI-027"
              ]
            },
            {
              "itemId": "ARCH-06",
              "roles": [
                "constraint"
              ],
              "rationale": "Die Annahme, dass vorhandene Akten im Alltag schwer nutzbar sind, begründet einen Rahmen für die Bewertung von Dokumentationsintegration und schnellen Zugriffen.",
              "targetPbiIds": [
                "PBI-006",
                "PBI-027"
              ]
            },
            {
              "itemId": "ARCH-07",
              "roles": [
                "design",
                "constraint"
