  },
  {
    "itemId": "ARCH-27",
    "text": "Es soll erwogen werden, in der Profilübersicht das Anlegen neuer Profile per Plus-Symbol und Dialog für Bild, Name und Beschreibung zu ermöglichen.",
    "rationale": "Das Anlegen neuer Profile per Plus-Symbol und Dialog ist derzeit ein erwogener Lösungsansatz und damit vor allem als Architekturidee zu dokumentieren.",
    "sourceClaimIds": [
      "canon-neue-profile-anlegen-pruefen"
    ]
  },
  {
    "itemId": "ARCH-29",
    "text": "Nach dem Login soll auf jeder Seite eine konsistente Appbar vorhanden sein.",
    "rationale": "Eine konsistente Appbar nach dem Login ist eine UI-Architekturentscheidung und bindet alle betroffenen Navigationsseiten.",
